"""Tests for the eval-approver identity and the canonical Approval name."""

from __future__ import annotations

import unittest

from pagerless_eval.approver import APPROVER_USER, approval_name

from tests.support import HASH, triage

# Generated by api/v1alpha1.TriageApprovalName for the triage below, so the
# harness computes exactly the name that the admission webhook requires.
EXPECTED = "decision-d5756dv6iml47b3b3iyz7xxwoaj6mn2vqm2bslsoprcovdjztmuq"


class ApprovalNameTest(unittest.TestCase):
    def test_the_name_matches_the_go_implementation(self) -> None:
        self.assertEqual(approval_name(triage(), HASH), EXPECTED)

    def test_a_different_proposal_hash_changes_the_name(self) -> None:
        self.assertNotEqual(approval_name(triage(), HASH), approval_name(triage(), "cd" * 32))

    def test_a_different_triage_uid_changes_the_name(self) -> None:
        self.assertNotEqual(approval_name(triage(), HASH), approval_name(triage(uid="uid-2"), HASH))

    def test_a_recreated_triage_with_the_same_name_does_not_reuse_a_decision(self) -> None:
        self.assertNotEqual(
            approval_name(triage(), HASH),
            approval_name(triage(uid="another-uid"), HASH),
        )

    def test_the_name_is_a_bounded_dns_label(self) -> None:
        name = approval_name(triage(name="x" * 252), HASH)
        self.assertLessEqual(len(name), 63)
        self.assertRegex(name, r"^[a-z0-9-]+$")

    def test_the_approver_identity_is_the_documented_user(self) -> None:
        self.assertEqual(APPROVER_USER, "eval-approver")


if __name__ == "__main__":
    unittest.main()
